import { textOf, valueOf, withTitle, type Field, type Rec } from "./fields"
import type { FieldDef, FilterRule, ViewConfig } from "./types"

function matches(item: Rec, rule: FilterRule, field: Field): boolean {
  const have = textOf(valueOf(item, field.key))
  const wants = Array.isArray(rule.value)
    ? rule.value
    : rule.value === ""
      ? []
      : [rule.value]
  // a rule with no value yet is inert so a half-built filter never empties the view
  if (wants.length === 0) return true
  switch (rule.op) {
    case "contains":
      return wants.some((w) => have.toLowerCase().includes(w.toLowerCase()))
    case "is":
    case "anyOf":
      return wants.includes(have)
    case "isNot":
      return !wants.includes(have)
    case "onOrBefore":
      return have !== "" && have <= wants[0]
    case "onOrAfter":
      return have !== "" && have >= wants[0]
    case "gte":
      return have !== "" && Number(have) >= Number(wants[0])
    case "lte":
      return have !== "" && Number(have) <= Number(wants[0])
  }
}

function compare(field: Field, a: string, b: string): number {
  if (field.type === "select") {
    const options = field.options ?? []
    const rank = (v: string) => {
      const i = options.indexOf(v)
      return i === -1 ? options.length : i
    }
    return rank(a) - rank(b)
  }
  if (field.type === "number") return Number(a) - Number(b)
  return a < b ? -1 : a > b ? 1 : 0
}

/**
 * Filters, searches and sorts `items` for one view without touching the input.
 * Filter rules are ANDed, search matches the title and text fields, and empty
 * values sort last in either direction.
 */
export function applyView<T extends { id: string; title: string }>(
  items: T[],
  view: ViewConfig,
  fields: FieldDef<T>[],
  query = ""
): T[] {
  const defs = withTitle(fields)
  const rules = view.filters.flatMap((rule) => {
    const field = defs.find((f) => f.key === rule.field)
    return field ? [{ rule, field }] : []
  })
  const needle = query.trim().toLowerCase()
  const searchable = defs.filter((f) => f.type === "text")

  const kept = items.filter(
    (item) =>
      rules.every(({ rule, field }) => matches(item, rule, field)) &&
      (needle === "" ||
        searchable.some((f) =>
          textOf(valueOf(item, f.key)).toLowerCase().includes(needle)
        ))
  )

  const sortField = view.sort && defs.find((f) => f.key === view.sort?.field)
  if (!view.sort || !sortField) return kept
  const sign = view.sort.dir === "desc" ? -1 : 1
  return [...kept].sort((a, b) => {
    const av = textOf(valueOf(a, sortField.key))
    const bv = textOf(valueOf(b, sortField.key))
    if (av === "" || bv === "") return av === bv ? 0 : av === "" ? 1 : -1
    return sign * compare(sortField, av, bv)
  })
}

import { PlusIcon } from "lucide-react"

import { EmptyState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import { displayValue, pickField, valueOf } from "./fields"
import { buildColumns } from "./grouping"
import { recordClasses, recordProps, type LayoutProps } from "./layout-shared"

export function BoardLayout(props: LayoutProps) {
  const { items, fields, view, noun, onCreate } = props
  const groupField = pickField(fields, view.groupBy, "select")
  if (!groupField) {
    return (
      <EmptyState
        title="Board needs a select field"
        description="Add a field with a fixed list of options to group cards by."
      />
    )
  }
  const columns = buildColumns(items, groupField)
  const others = fields.filter(
    (f) => f.key !== "title" && f.key !== groupField.key
  )

  return (
    <div className="flex h-full gap-3 overflow-x-auto p-3">
      {columns.map((column) => (
        <section
          key={column.value || "__none__"}
          aria-label={`${column.label}, ${column.items.length}`}
          className="flex w-[260px] shrink-0 flex-col rounded-lg bg-muted/40"
        >
          <header className="flex h-8 shrink-0 items-center gap-2 px-2 text-xs">
            <span className="min-w-0 truncate font-medium">{column.label}</span>
            <span className="text-muted-foreground tabular-nums">
              {column.items.length}
            </span>
            {onCreate ? (
              <Button
                variant="ghost"
                size="icon-xs"
                className="ml-auto"
                aria-label={`New ${noun} in ${column.label}`}
                onClick={() =>
                  onCreate({ [groupField.key]: column.value || undefined })
                }
              >
                <PlusIcon />
              </Button>
            ) : null}
          </header>
          <div className="flex min-h-0 flex-1 flex-col gap-1.5 overflow-y-auto px-1.5 pb-1.5">
            {column.items.map((item) => {
              const details = others
                .map((f) => displayValue(f, valueOf(item, f.key)))
                .filter((text) => text !== "")
                .join(" · ")
              return (
                <button
                  key={item.id}
                  type="button"
                  {...recordProps(props, item.id)}
                  className={cn(
                    "flex w-full cursor-pointer flex-col gap-1 rounded-md border bg-card p-2 text-left text-xs shadow-xs hover:bg-accent/50",
                    recordClasses
                  )}
                >
                  <span className="line-clamp-2 font-medium" title={item.title}>
                    {item.title}
                  </span>
                  {details ? (
                    <span className="truncate text-muted-foreground">
                      {details}
                    </span>
                  ) : null}
                </button>
              )
            })}
          </div>
        </section>
      ))}
    </div>
  )
}

import { useMemo } from "react"
import { ChevronLeftIcon, ChevronRightIcon, PlusIcon } from "lucide-react"

import { EmptyState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import {
  addMonths,
  formatDay,
  formatMonth,
  isIsoDate,
  monthGrid,
  startOfMonth,
  toIso,
  weekdayLabels,
} from "./dates"
import { pickField, textOf, valueOf, type Rec } from "./fields"
import { recordClasses, recordProps, type LayoutProps } from "./layout-shared"

const CARDS_PER_DAY = 3

function Chip({
  layout,
  item,
  tabStopId,
}: {
  layout: LayoutProps
  item: Rec
  tabStopId: string | null
}) {
  return (
    <button
      type="button"
      {...recordProps(layout, item.id, tabStopId)}
      title={item.title}
      className={cn(
        "block w-full cursor-pointer truncate rounded border bg-card px-1.5 py-0.5 text-left text-[11px] leading-4 hover:bg-accent/50",
        recordClasses
      )}
    >
      {item.title}
    </button>
  )
}

export interface CalendarLayoutProps extends LayoutProps {
  month: Date
  onMonthChange(month: Date): void
}

export function CalendarLayout(props: CalendarLayoutProps) {
  const {
    items,
    fields,
    view,
    noun,
    month,
    onMonthChange,
    onCreate,
    tabStopId,
  } = props
  const dateField = pickField(fields, view.dateField, "date")
  const weekdays = useMemo(() => weekdayLabels(), [])
  const days = useMemo(() => monthGrid(month), [month])

  const byDay = useMemo(() => {
    const map = new Map<string, Rec[]>()
    if (!dateField) return map
    for (const item of items) {
      const value = textOf(valueOf(item, dateField.key))
      if (isIsoDate(value)) map.set(value, [...(map.get(value) ?? []), item])
    }
    return map
  }, [items, dateField])

  if (!dateField) {
    return (
      <EmptyState
        title="Calendar needs a date field"
        description="Add a field that holds a date to place records on the month grid."
      />
    )
  }

  // a Tab stop hidden behind "+N more" would leave the grid unreachable
  const visibleIds = days.flatMap((d) =>
    (byDay.get(toIso(d)) ?? []).slice(0, CARDS_PER_DAY).map((i) => i.id)
  )
  const stop =
    tabStopId && visibleIds.includes(tabStopId)
      ? tabStopId
      : (visibleIds[0] ?? null)
  const today = toIso(new Date())

  return (
    <div className="flex h-full flex-col">
      <div className="flex h-9 shrink-0 items-center gap-1 px-3">
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label="Previous month"
          onClick={() => onMonthChange(addMonths(month, -1))}
        >
          <ChevronLeftIcon />
        </Button>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label="Next month"
          onClick={() => onMonthChange(addMonths(month, 1))}
        >
          <ChevronRightIcon />
        </Button>
        <h3 aria-live="polite" className="px-1 text-sm font-medium">
          {formatMonth(month)}
        </h3>
        <Button
          variant="outline"
          size="xs"
          className="ml-auto"
          onClick={() => onMonthChange(startOfMonth(new Date()))}
        >
          Today
        </Button>
      </div>
      <div className="min-h-0 flex-1 overflow-auto">
        <ol
          className="grid min-w-[42rem] grid-cols-7 border-t"
          aria-label={formatMonth(month)}
        >
          {weekdays.map((name) => (
            <li
              key={name}
              aria-hidden
              className="sticky top-0 z-10 border-b bg-background px-2 py-1 text-[11px] font-medium text-muted-foreground"
            >
              {name}
            </li>
          ))}
          {days.map((day) => {
            const iso = toIso(day)
            const records = byDay.get(iso) ?? []
            const inMonth = day.getMonth() === month.getMonth()
            const weekend = day.getDay() === 0 || day.getDay() === 6
            const extra = records.slice(CARDS_PER_DAY)
            return (
              <li
                key={iso}
                className={cn(
                  "group/day flex min-h-[6.5rem] min-w-0 flex-col gap-1 border-r border-b p-1 [&:nth-child(7n+7)]:border-r-0",
                  weekend && "bg-muted/40",
                  !inMonth && "bg-muted/20"
                )}
              >
                <div className="flex h-5 items-center justify-between">
                  <time
                    dateTime={iso}
                    className={cn(
                      "flex h-5 min-w-5 items-center justify-center rounded-full px-1 text-[11px] tabular-nums",
                      iso === today
                        ? "bg-primary font-medium text-primary-foreground"
                        : inMonth
                          ? "text-foreground"
                          : "text-muted-foreground/60"
                    )}
                  >
                    {day.getDate()}
                  </time>
                  {onCreate ? (
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      className="opacity-0 group-focus-within/day:opacity-100 group-hover/day:opacity-100"
                      aria-label={`New ${noun} on ${iso}`}
                      onClick={() => onCreate({ [dateField.key]: iso })}
                    >
                      <PlusIcon />
                    </Button>
                  ) : null}
                </div>
                <div
                  className={cn(
                    "flex flex-col gap-0.5",
                    !inMonth && "opacity-60"
                  )}
                >
                  {records.slice(0, CARDS_PER_DAY).map((item) => (
                    <Chip
                      key={item.id}
                      layout={props}
                      item={item}
                      tabStopId={stop}
                    />
                  ))}
                  {extra.length > 0 ? (
                    <Popover>
                      <PopoverTrigger asChild>
                        <button
                          type="button"
                          className="rounded px-1.5 text-left text-[11px] text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
                        >
                          +{extra.length} more
                        </button>
                      </PopoverTrigger>
                      <PopoverContent className="w-56 gap-1 p-1.5">
                        <p className="px-1 text-xs font-medium">
                          {formatDay(iso)}
                        </p>
                        {extra.map((item) => (
                          <Chip
                            key={item.id}
                            layout={props}
                            item={item}
                            tabStopId={null}
                          />
                        ))}
                      </PopoverContent>
                    </Popover>
                  ) : null}
                </div>
              </li>
            )
          })}
        </ol>
      </div>
    </div>
  )
}

import type { RefObject } from "react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"

/** Centered confirmation for a destructive action. */
export function ConfirmDialog({
  open,
  title,
  description,
  confirmLabel,
  returnFocusRef,
  onConfirm,
  onOpenChange,
}: {
  open: boolean
  title: string
  description: string
  confirmLabel: string
  /** Where focus goes on close; the dialog has no trigger element to return it to. */
  returnFocusRef: RefObject<HTMLElement | null>
  onConfirm(): void
  onOpenChange(open: boolean): void
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        showCloseButton={false}
        onCloseAutoFocus={(e) => {
          e.preventDefault()
          returnFocusRef.current?.focus()
        }}
      >
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button
            variant="destructive"
            onClick={() => {
              onOpenChange(false)
              onConfirm()
            }}
          >
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

const ISO = /^\d{4}-\d{2}-\d{2}$/

export function isIsoDate(value: unknown): value is string {
  return typeof value === "string" && ISO.test(value)
}

export function toIso(date: Date): string {
  const pad = (n: number) => String(n).padStart(2, "0")
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

export function fromIso(iso: string): Date {
  const [year, month, day] = iso.split("-").map(Number)
  return new Date(year, month - 1, day)
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1)
}

export function addMonths(date: Date, count: number): Date {
  return new Date(date.getFullYear(), date.getMonth() + count, 1)
}

/** Six Sunday-first weeks covering `month`, so the grid never changes height. */
export function monthGrid(month: Date): Date[] {
  const first = startOfMonth(month)
  return Array.from(
    { length: 42 },
    (_, i) =>
      new Date(first.getFullYear(), first.getMonth(), 1 - first.getDay() + i)
  )
}

export function formatDay(iso: string): string {
  if (!isIsoDate(iso)) return iso
  return new Intl.DateTimeFormat(undefined, {
    day: "numeric",
    month: "short",
  }).format(fromIso(iso))
}

export function formatMonth(date: Date): string {
  return new Intl.DateTimeFormat(undefined, {
    month: "long",
    year: "numeric",
  }).format(date)
}

export function weekdayLabels(): string[] {
  const format = new Intl.DateTimeFormat(undefined, { weekday: "short" })
  return Array.from({ length: 7 }, (_, i) =>
    format.format(new Date(2024, 0, 7 + i))
  )
}

