function Cell({ field, raw }: { field: Field; raw: unknown }) {
  const text = displayValue(field, raw)
  if (text === "") return null
  if (field.type === "select") return <Badge variant="secondary">{text}</Badge>
  return (
    <span className={cn(field.type === "number" && "tabular-nums")}>
      {text}
    </span>
  )
}

