  const current = pickField(fields, board ? view.groupBy : view.dateField, type)
  const label = board ? "Group by" : "Date field"
  return (
    <Select
      value={current?.key}
      disabled={disabled}
      onValueChange={(key) =>
        onChange(board ? { groupBy: key } : { dateField: key })
      }
    >
      <SelectTrigger
        size="sm"
